    assert_eq!(issues.len(), 2);
    assert_eq!(issues[0].mechanic, SpellCoverageMechanic::Effect);
    assert_eq!(issues[0].mechanic_id, 28);
    assert_eq!(issues[0].support, SpellMechanicSupport::Pending("summon"));
